'use strict';
const S=SkySourcing;let sourcing;try{sourcing=JSON.parse(localStorage.getItem(S.KEY))}catch{}if(!sourcing||!Array.isArray(sourcing.rfqs))sourcing=S.initial();
const sourceBaseRender=render,sourceBaseFleet=fleetPage,sourceBaseActions=actions,sourceBaseNetwork=network,sourceBaseControl=controlTower,sourceBaseComponent=componentEditor;
nav.splice(nav.length-1,0,['Quotes & shipping','file'],['Value calculator','chart']);
function sourceSave(){sourcing.calendarBase=SkyCalendar.BASE;try{localStorage.setItem(S.KEY,JSON.stringify(sourcing))}catch{saved=false}}
function sourceEvent(msg){audit(msg);sourceSave();save();render();toast(msg)}
function sourceGo(view){close();state.role='Buyer';state.view=view;save();sourceSave();render();window.scrollTo({top:0,behavior:'instant'})}
function option(v,label,selected){return `<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(label)}</option>`}
function planningBar(){return `<label class="planning-window-control"><span>Planning horizon</span><select id="planning-horizon" aria-label="Planning horizon">${Object.entries(S.modes).map(([k,m])=>option(k,k==='urgent'?'AOG / urgent · next 7 days':k==='short'?'Short term · next 90 days':'Long term · 6–24 months',sourcing.mode)).join('')}</select></label>`}
render=function(){if(state.view==='Analytics lab')state.view='Metrics & Forecasting';sourceBaseRender();for(const n of document.querySelectorAll('nav button'))if(n.dataset.action==='nav-Marketplace')n.querySelector('span').textContent='Supplier search';if(state.role==='Buyer'){const views={'Marketplace':sourcePage,'Quotes & shipping':quotePage,'Value calculator':valuePage};if(views[state.view])$('main').innerHTML=views[state.view]()+`<footer><span>Scenario saved locally</span><span>Synthetic sourcing · no external systems contacted</span></footer>`;if(state.view==='Control tower')$('main .heading-actions')?.insertAdjacentHTML('afterbegin',planningBar());if(state.view==='Supplier network')$('main').insertAdjacentHTML('afterbegin',supplierSearchEntry())}else{$('main footer')?.insertAdjacentHTML('beforebegin',supplierParticipation())}presentationPolish()};
function supplierSearchEntry(){return `<section class="panel source-entry"><div><span class="eyebrow">FROM CAPABILITY TO AN EXACT PART</span><h3>Compare multiple sources for one component.</h3><p>Search the synthetic catalog by part number, component or supplier.</p></div>${btn('Open supplier search','src-search-home','primary','search')}</section>`}
controlTower=function(){if(sourcing.mode==='short')return sourceBaseControl();const airline=lab.org==='Airline',urgent=sourcing.mode==='urgent',jobs=A.airlineJobs(D,lab,state).filter(j=>S.inMode(j.due,sourcing.mode)),rem=A.reminders(D,lab).filter(r=>S.inMode(r.target,sourcing.mode)),rows=A.oemRows(D,lab,state).filter(r=>S.inMode(r.due,sourcing.mode));return `${heading(urgent?'URGENT MATERIAL DESK':'LONG-RANGE READINESS',urgent?'Find the fastest<br><em>feasible response.</em>':'Prepare for what<br><em>comes next.</em>',urgent?'Needs due in the next seven days. Urgency does not imply stock or transport is available.':'Planning targets and scenario assumptions from six months onward; no delivery or capacity guarantee.',btn('Find sourcing options','src-search-home','primary','search'))}${simNote()}${horizonHero(airline,urgent,urgent?(airline?jobs.filter(j=>j.gap).length:rows.filter(r=>r.gap).length):(airline?rem.length:rows.filter(r=>r.gap).length))}${airline?labMetrics([['Work orders in window',jobs.length,'Dated sample MRO schedule'],['Jobs with material gaps',jobs.filter(j=>j.gap).length,'Not a dispatch determination'],['Component targets',rem.length,'Planning assumptions only']]):labMetrics([['Component lines in window',rows.length,'Actual sample need dates'],['Lines with gaps',rows.filter(r=>r.gap).length,'No invented urgent production orders'],['Supplier signals to review',forecastRows().filter(r=>r.f.stale||r.f.missing).length,'Organization-wide freshness context']])}<section class="panel"><div class="panel-head"><div><h2>${airline?'Maintenance needs in this window':'Production needs in this window'}</h2><p>${urgent?'Today through '+date(S.add(S.BASE,7)):'From '+date(S.add(S.BASE,180))+'; detailed work-order schedule covers only the next eight weeks.'}</p></div></div>${airline?(jobs.length?jobsTable(jobs):'<p>No scheduled work orders in this window. Review component targets below or change planning window.</p>'):(rows.length?oemTable(rows):'<p>No dated production requirements in this window in the current ERP sample. The long-range outlook below is an assumed scenario, not a confirmed build schedule.</p>')}</section>${!urgent?`<section class="panel"><span class="eyebrow">${airline?'PROJECTED COMPONENT NEEDS':'ASSUMED 24-MONTH HOUSING TRAJECTORY'}</span>${airline?`<div class="table-scroll"><table><thead><tr><th>Aircraft / component</th><th>Planning target</th><th>Reorder by</th><th></th></tr></thead><tbody>${rem.map(r=>`<tr><td>${r.aircraft}<small>${r.part.name}</small></td><td>${date(r.target)}</td><td>${date(r.reorder)}</td><td>${btn('Inspect targets','lab-component-'+r.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:lineChart(A.outlook(D,lab,state))}<p class="fine-print">${airline?'Targets depend on the current sample usage assumptions. Maintenance-program references require review.':'Assumes 1.2% monthly demand growth and 0.6% output growth for 12 months. Bands ±20% then ±35%; not a trained demand forecast.'}</p></section>`:''}<section class="panel">${btn('Review maintenance program references','src-programs','','file')}${btn('Inspect delivery metrics','lab-nav-Metrics & Forecasting','','chart')}</section>`};
function sourcePage(){const found=S.filter(D,sourcing),selected=sourcing.selected.filter(id=>S.offers(D).some(o=>o.id===id&&o.partId===sourcing.partId));return `${heading('ASSISTED SOURCING / MULTIPLE SOURCES','One need.<br><em>More ways forward.</em>','Find a component, compare possible sources, and prepare one RFQ for the suppliers you choose.',btn('View quote workspace','nav-Quotes & shipping','','arrow'))}${simNote('Local search over 72 synthetic listings. No live AI, ILS, broker, OEM database or carrier is contacted. Licensed-feed cards demonstrate an intended connection, not access to that provider.')}<section class="panel sourcing-assistant"><span class="eyebrow">SOURCING ASSISTANT · GUIDED DEMO</span><h2>Tell us which part you need.</h2><form id="src-assistant"><input name="prompt" aria-label="Describe the sourcing need" placeholder="Find 20 DEMO-BOLT-131 urgently" required maxlength="300"><button class="btn primary" type="submit">Find options ${icon('spark')}</button></form><div class="example-prompts">${btn('Find 20 bolts urgently','src-example-bolt','small')}${btn('Compare an APU replacement','src-example-apu','small')}${btn('Source 100 housings','src-example-housing','small')}</div><p class="fine-print">Try a demo part number or component name, with a quantity and urgency. Confirm the need in the filters and RFQ.</p></section><div class="sourcing-layout"><aside class="panel sourcing-filters"><h3>Define the need</h3><form id="src-filters"><label>Component<select name="partId" aria-label="Sourcing component">${option('all','All components',sourcing.partId)}${D.catalog.map(p=>option(p.id,p.name+' · '+p.code,sourcing.partId)).join('')}</select></label><label>Search text<input name="query" value="${esc(sourcing.query)}" placeholder="Supplier, part or location"></label><label>Supplier<select name="supplier">${option('all','All suppliers',sourcing.supplier)}${D.suppliers.map(s=>option(s.id,s.name,sourcing.supplier)).join('')}</select></label><label>Source type<select name="channel">${['all','Participating supplier','Catalog snapshot','Licensed-feed preview'].map(x=>option(x,x==='all'?'All source types':x,sourcing.channel)).join('')}</select></label><label>Condition<select name="condition">${['all','New','Serviceable'].map(x=>option(x,x==='all'?'All conditions':x,sourcing.condition)).join('')}</select></label><label>Earliest possible handling + transit<select name="delivery">${[['all','Any timing'],['2','Within 2 days'],['7','Within 7 days']].map(([v,l])=>option(v,l,sourcing.delivery)).join('')}</select></label><button class="btn primary" type="submit">Apply filters</button>${btn('Clear filters','src-clear','small')}</form></aside><section><div class="source-result-head"><div><strong>${found.length} possible sources</strong><p>Availability and documentation require supplier review.</p></div>${btn('Prepare RFQ · '+selected.length,'src-draft','primary','file')}</div><div class="source-cards">${found.map(o=>{const p=D.catalog.find(p=>p.id===o.partId);return `<article class="panel source-card"><div class="source-card-top"><span class="code">${p.code}</span>${pill(o.channel)}</div><h3>${p.name}</h3><p>${o.name}<small>${o.kind} · ${o.location}</small></p><div class="source-facts"><div><span>Listed quantity</span><strong>${o.qty.toLocaleString()}</strong></div><div><span>Unit price</span><strong>${o.showPrice?money(o.price):'Quote required'}</strong></div><div><span>Earliest scenario arrival</span><strong>${date(S.add(S.BASE,o.handling+1))}</strong></div><div><span>Condition</span><strong>${o.condition}</strong></div></div><p class="trace-note">${icon(o.docs?'file':'warning')}${o.docs?'Sample trace pack · eligibility review required':'Documentation missing · cannot convert quote'}</p><p class="fine-print">Listed ${date(o.updated)}${o.updated<S.add(S.BASE,-2)?' · stale snapshot':''}. Part/model fit unverified. Timing = handling + fastest assumed transit, not a quote.</p><label class="source-select"><input type="checkbox" data-source-id="${o.id}" ${selected.includes(o.id)?'checked':''}> Compare / request quote</label></article>`}).join('')||'<section class="panel empty"><h3>No sources match.</h3><p>Try another component or clear filters. No availability is inferred from a missing result.</p></section>'}</div></section></div>`}
function rfqDraft(){const selected=S.offers(D).filter(o=>sourcing.selected.includes(o.id));if(!selected.length||new Set(selected.map(o=>o.partId)).size!==1)return toast('Select one or more sources for the same exact component.');const p=D.catalog.find(p=>p.id===selected[0].partId),jobs=D.jobs.filter(j=>j.partId===p.id);open('Prepare a request for quotation',`<h3>${p.name} · ${p.code}</h3><p>${selected.length} selected suppliers. This draft will stay local until you release the simulated request.</p><ul>${selected.map(o=>`<li>${o.name} · ${o.channel}</li>`).join('')}</ul><form id="src-rfq-draft"><div class="form-grid"><label>Quantity<input name="qty" type="number" value="${sourcing.qty}" min="1" max="100000" step="1" required></label><label>Need by<input name="due" type="date" value="${sourcing.due}" min="${S.BASE}" required></label><label>Destination<select name="destination">${['PHX','DFW','DEN','MIA'].map(x=>option(x,x,sourcing.destination)).join('')}</select></label><label>Required condition<select name="requiredCondition"><option value="Any">Any listed condition · review required</option><option value="New">NE · New</option><option value="Serviceable">SV · Serviceable</option></select></label><label>Documentation required<input name="documents" value="Release documents and trace history" maxlength="160" required></label><label>Responsible buyer<input name="owner" value="Alex Chen" maxlength="80" required></label>${lab.org==='Airline'?`<label>Maintenance job<select name="jobId" required><option value="">Choose a matching work order</option>${jobs.map(j=>option(j.id,j.id+' · '+date(j.due),'')).join('')}</select></label>`:''}</div><p class="fine-print">Purchase sourcing only. Loaners remain in Fleet & maintenance. Missing documentation and partial quotes cannot become purchase requests in this demo.</p><button class="btn primary" type="submit">Save RFQ draft</button></form>`)}
function quotePage(){const rows=sourcing.rfqs.filter(r=>r.org===lab.org);return `${heading('RFQ WORKSPACE / BUYER CONTROL','From a search<br><em>to a reviewed decision.</em>','Prepare requests, compare supplier responses and choose a delivery option.',btn('Find more sources','src-search-home','','search'))}${simNote('RFQ release and responses are local simulations. No supplier receives a message; shipping costs and transit times are fictional and exclude taxes, duties and damage.')}<div class="action-list">${rows.length?rows.slice().reverse().map(r=>{const p=D.catalog.find(p=>p.id===r.partId);return `<section class="panel rfq-card"><div class="action-top"><span class="code">${r.id} · ${r.org}</span>${pill(r.actionRef?'Request created':r.status,r.actionRef?'green':'amber')}</div><h2>${p.name}</h2><p>${r.qty} units · ${r.destination} · needed ${date(r.due)} · ${esc(r.owner)}${r.jobId?' · '+r.jobId:''}</p><p class="fine-print">${r.ids.length} selected sources · snapshot ${date(r.created)} · Required condition: ${esc(r.requiredCondition||'Any')} · Documents: ${esc(r.documents||'Release documents and trace history')}</p>${r.status==='Draft'?`${btn('Review & release demo RFQ','src-release-'+r.id,'primary','check')}${btn('Discard draft','src-discard-'+r.id,'small')}`:r.status==='Awaiting responses'?btn('Simulate supplier responses','src-responses-'+r.id,'primary','refresh'):quoteTable(r)}<details><summary>Activity · ${r.events.length} steps</summary><ul>${r.events.map(e=>`<li>${esc(e.text)} · ${date(e.at)}</li>`).join('')}</ul></details></section>`}).join(''):`<section class="panel empty"><h2>No RFQs for this organization.</h2><p>Choose a component and select sources in Supplier search.</p>${btn('Start a supplier search','src-search-home','primary')}</section>`}</div>`}
function quoteTable(r){return `<label class="shipping-selector">Compare using<select data-rfq-service="${r.id}" aria-label="Shipping service for ${r.id}" ${r.actionRef?'disabled':''}>${[['standard','Standard parcel / scheduled freight'],['express','Express parcel / expedited freight'],['courier','Dedicated courier']].map(([k,l])=>option(k,l,r.shipping)).join('')}</select></label><div class="table-scroll"><table><thead><tr><th>Supplier / response</th><th>Quoted quantity / unit</th><th>Shipping</th><th>Arrival</th><th>Total delivered estimate</th><th></th></tr></thead><tbody>${r.quotes.map(q=>{const sh=chosenShipping(r,q);return `<tr><td>${q.name}<small>${q.status} · ${q.condition}</small></td><td>${q.quotedQty} / ${money(q.unitPrice)}<small>Valid through ${date(q.validThrough)} · fixed snapshot</small></td><td>${money(sh.cost)}<small>${esc(sh.provider||'Carrier estimate')} · ${sh.name} · ${q.handling}d handling + ${sh.transit}d transit</small></td><td>${date(sh.arrival)}<small>${sh.arrival<=r.due?'Within need date':'After need date'}</small></td><td>${money(q.unitPrice*q.quotedQty+sh.cost)}<small>${q.quotedQty<r.qty?'Partial quantity only; not a full-need total':'Parts + shipping; taxes excluded'}</small></td><td>${r.actionRef?pill(r.chosenQuote===q.id?'Selected':'Not selected'):q.docs&&q.quotedQty>=r.qty&&(!r.requiredCondition||r.requiredCondition==='Any'||q.condition===r.requiredCondition)?btn('Review option','src-option-'+r.id+'~'+q.id,'small','arrow'):pill('Review needed','amber')}</td></tr>`}).join('')}</tbody></table></div>${carrierComparison(r)}${r.actionRef?`<p class="request-linked">${icon('check')}${r.actionRef} is in Actions. Buyer approval and supplier acceptance still apply. Quote selection alone adds no stock or coverage.</p>${btn('Open request','nav-Actions','primary','arrow')}${shipmentPanel(r)}`:''}`}
function linkedRequest(r){return (r.org==='OEM'?state.actions:lab.actions).find(a=>a.id===r.actionRef)}
function shipmentPanel(r){const a=linkedRequest(r);return `<div class="shipment-panel"><strong>Shipment progress · ${esc(r.shipment||'Not scheduled')}</strong><div class="shipment-track">${['Not scheduled','Ready for dispatch','In transit','Delivered (simulation)'].map((step,i)=>`<span class="${i<=['Not scheduled','Ready for dispatch','In transit','Delivered (simulation)'].indexOf(r.shipment||'Not scheduled')?'reached':''}"><i>${i+1}</i>${step.replace(' (simulation)','')}</span>`).join('')}</div><p>${a?.status==='Confirmed'?'Supplier acceptance recorded. Step through the fictional logistics updates.':'Waiting for supplier acceptance before logistics can progress.'}</p>${a?.status==='Confirmed'&&r.shipment!=='Delivered (simulation)'?btn('Simulate shipment update','src-shipment-'+r.id,'small','truck'):''}<small>No carrier is contacted. Delivered status does not post a warehouse receipt; inventory reconciliation is a separate step.</small></div>`}
function optionReview(rid,qid){const r=sourcing.rfqs.find(r=>r.id===rid),pick=S.selection(D,r,qid,r.shipping);open('Review sourcing and shipping',`<h3>${pick.quote.name}</h3>${labMetrics([['Parts',money(pick.partCost),r.qty+' units'],['Shipping',money(pick.service.cost),pick.service.name],['Total estimate',money(pick.total),'Taxes and duties excluded']])}<p>${esc(pick.service.provider||'Carrier estimate')} · Expected arrival ${date(pick.service.arrival)} · ${pick.onTime?'within':'after'} need date ${date(r.due)}.</p><p>Source: ${pick.quote.channel}. Documentation supplied for review; configuration, traceability and supplier eligibility require authorized approval.</p><p class="fine-print">Booking is subject to packaging, weight, dimensions and handling requirements. Engines and APUs require specialist transport arrangements.</p><form id="src-convert" data-rfq="${r.id}" data-quote="${qid}"><label class="check-label"><input type="checkbox" name="ack" required><span>I reviewed the fictional terms and documentation assumptions. Create a request for buyer review; no real order is placed.</span></label><button class="btn primary" type="submit">Create purchase review request</button></form>`)}
function convertQuote(rid,qid){const r=sourcing.rfqs.find(r=>r.id===rid),pick=S.selection(D,r,qid,r.shipping),q=pick.quote,sh=pick.service;const otherOrgHeld=[...state.actions,...lab.actions].filter(a=>a.quoteOfferId===q.id&&!['Rejected','Declined','Cancelled'].includes(a.status)).reduce((n,a)=>n+a.qty,0);if(otherOrgHeld+r.qty>q.qty)throw Error('Other requests have used this listing quantity. Start a new RFQ.');let a;if(r.org==='OEM'){const part=state.parts.find(p=>p.id===r.partId);if(!part)throw Error('This component is outside the OEM production catalog. Use an airline work order.');const id='iq_'+q.id;let offer=state.offers.find(o=>o.id===id);if(!offer){offer={id,partId:r.partId,supplier:q.supplier,name:q.name,qty:q.qty,price:q.unitPrice,days:sh.totalDays,location:q.location,channel:q.kind,condition:q.condition};state.offers.push(offer)}offer.days=sh.totalDays;offer.price=q.unitPrice;a=M.create(state,{partId:r.partId,type:'stock',sourceId:id,qty:r.qty,owner:r.owner});a.shippingCost=sh.cost;a.shippingService=(sh.provider?sh.provider+' · ':'')+sh.name;a.deliveryDestination=r.destination}else{const job=D.jobs.find(j=>j.id===r.jobId&&j.partId===r.partId);if(!job)throw Error('Choose a matching maintenance work order.');a=A.addAirlineAction(D,lab,r.jobId,'Purchase',r.qty,r.owner);a.supplier=q.supplier;a.eta=sh.arrival;a.expense=pick.total;a.shippingCost=sh.cost;a.shippingService=(sh.provider?sh.provider+' · ':'')+sh.name}a.quoteRef=r.id;a.quoteOfferId=q.id;r.chosenQuote=q.id;r.chosenShipping={...sh};r.carrier=sh.id;r.actionRef=a.id;r.shipment='Not scheduled';r.events.push({text:'Created '+a.id+' for buyer review; '+(sh.provider||'')+' '+sh.name+' selected',at:S.BASE});audit(r.id+' created '+a.id+' from a reviewed quote.');labSave();sourceSave();save();close();sourceGo('Actions');toast(a.id+' created. Supplier acceptance is still required.')}
function programPanel(){return `<section class="panel program-panel"><div class="panel-head"><div><span class="eyebrow">MAINTENANCE PROGRAM / SOURCE REGISTER</span><h2>Keep the planning basis visible.</h2><p>Reference the applicable OEM maintenance program and operator-approved schedule before using targets operationally. No actual program is supplied or validated here.</p></div></div><div class="table-scroll"><table><thead><tr><th>Fleet context</th><th>Program reference / revision</th><th>Source status</th><th></th></tr></thead><tbody>${['B737-800','A320-200'].map(type=>{const p=sourcing.programs[type];return `<tr><td>${type}</td><td>${p?esc(p.reference)+'<small>Revision '+esc(p.revision)+' · '+esc(p.owner)+'</small>':'Not provided'}</td><td>${pill(p?'User-entered · unverified':'Source required','amber')}<small>Current targets remain sample assumptions.</small></td><td>${btn('Edit reference','src-program-'+type,'small','file')}</td></tr>`}).join('')}</tbody></table></div><p class="fine-print">References document the intended planning basis; adding one does not import tasks, change limits, establish component fit or approve maintenance. Reorder dates still use the displayed sample targets, usage, lead time and buffer.</p></section>`}
fleetPage=function(){return sourceBaseFleet()+programPanel()};
componentEditor=function(id){sourceBaseComponent(id);const comp=D.installed.find(c=>c.id===id),type=D.fleet.find(a=>a.id===comp?.aircraft)?.type,p=sourcing.programs[type];$('#dialog .dialog-body').insertAdjacentHTML('afterbegin',`<p class="program-callout"><strong>Program reference:</strong> ${p?esc(p.reference)+' · revision '+esc(p.revision)+' (unverified)':'Not provided for '+esc(type)}. Targets below remain sample planning assumptions.</p>`)};
function programEditor(type){const p=sourcing.programs[type]||{reference:'',revision:'',owner:''};open('Maintenance-program reference · '+type,`<form id="src-program-form" data-type="${type}"><label>OEM / operator program document reference<input name="reference" value="${esc(p.reference)}" placeholder="Document identifier or title" maxlength="150" required></label><label>Revision / issue<input name="revision" value="${esc(p.revision)}" maxlength="80" required></label><label>Responsible reviewer<input name="owner" value="${esc(p.owner)}" maxlength="80" required></label><p class="fine-print">A reference only. No document is uploaded or verified. Do not enter confidential program content. Saving does not replace the sample component targets.</p><button class="btn primary" type="submit">Save reference</button></form>`)}
function valuePage(){const x=sourcing.roi,r=S.roi(x);return `${heading('VALUE CALCULATOR / EDITABLE ASSUMPTIONS','Show the effort.<br><em>Test the value.</em>','Estimate purchasing effort saved first. Evaluate possible delay exposure separately.')}${simNote('Illustrative assumptions, not observed customer savings or a recommended subscription price. Avoided delays are speculative; they are excluded from labor-only ROI.')}<div class="lab-layout"><section class="panel"><h2>Your monthly assumptions</h2><form id="src-roi">${[['requests','Sourcing requests per month',1],['before','Current minutes per request',1],['after','Assisted minutes per request',1],['hourly','Loaded labor cost · USD/hour',1],['subscription','Assumed subscription · USD/month',1],['events','Potential delay events avoided/month',.01],['days','Days avoided per event',.1],['dayCost','Assumed operational cost · USD/day',1]].map(([key,label,step])=>`<label>${label}<input name="${key}" aria-label="${label}" type="number" min="0" max="10000000" step="${step}" value="${x[key]}" required></label>`).join('')}<button class="btn primary" type="submit">Recalculate value</button></form></section><section><div class="value-results">${labMetrics([['Purchasing hours saved',r.hours.toFixed(1),'Monthly estimated effort reduction'],['Labor value',money(r.labor),'Hours saved × loaded rate'],['Net labor value',money(r.net),'Labor value − subscription'],['Labor break-even',r.breakEven===null?'Not reached':r.breakEven+' requests','At the selected effort/rate assumptions']])}</div><section class="panel roi-exposure"><span class="eyebrow">SEPARATE SCENARIO · NOT INCLUDED ABOVE</span><h2>${money(r.delay)}</h2><p>Potential monthly delay exposure avoided</p><p class="fine-print">${x.events} events × ${x.days} days × ${money(x.dayCost)}/day. This is an assumption, not a promised outcome. A missing component does not automatically ground an aircraft or produce this cost.</p></section><section class="panel prose"><h3>What a pilot should measure</h3><p>Record time per sourcing task before and after, quote turnaround, complete responses, delivery-date error and material wait time. Use measured outcomes before claiming savings.</p><p>Labor value represents capacity freed; it is not necessarily a cash expense reduction. Do not add labor and downtime estimates if their costs overlap.</p>${btn('Export calculator assumptions','src-roi-export','','download')}</section></section></div>`}
function supplierParticipation(){return `<section class="panel"><span class="eyebrow">SUPPLIER PARTICIPATION / BUSINESS-MODEL TEST</span><h2>More useful listings. Earlier conversations.</h2><p>Proposed free basic listing; an optional participation discount could recognize selected inventory/readiness sharing. Terms and pricing are not established. No enrollment or data transfer occurs here.</p><p class="fine-print">Suppliers choose fields and named partners. No requirement to share proprietary production details publicly; role preview is not secure authentication.</p></section>`}
actions=function(){return sourceBaseActions()+`<section class="panel"><h3>Quotes and delivery assumptions</h3><p>RFQ drafts and shipping comparisons live in Quotes & shipping. Selected options become the requests above and still need buyer approval and supplier acceptance.</p>${btn('Open quotes & shipping','nav-Quotes & shipping','','arrow')}${[...state.actions,...lab.actions].filter(a=>a.quoteRef&&(lab.org==='OEM'?state.actions.includes(a):lab.actions.includes(a))).map(a=>`<p class="quote-link"><strong>${a.id}</strong> · ${a.quoteRef} · ${esc(a.shippingService)} · ${money(a.shippingCost)} shipping${a.status==='Confirmed'?' · supplier accepted':''}</p>`).join('')}</section>`};
function setMode(mode){if(!S.modes[mode])return;sourcing.mode=mode;sourcing.due=S.add(S.BASE,S.modes[mode].days);sourceSave();render()}
function sourceExample(id,qty,urgent=false){sourcing.partId=id;sourcing.qty=qty;sourcing.query='';sourcing.supplier='all';sourcing.channel='all';sourcing.condition='all';sourcing.delivery='all';sourcing.selected=[];if(urgent){sourcing.mode='urgent';sourcing.due=S.add(S.BASE,2)}sourceGo('Marketplace')}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]'),act=el?.dataset.action;if(!act?.startsWith('src-'))return;e.preventDefault();e.stopImmediatePropagation();try{if(act.startsWith('src-job-source-')){const j=A.airlineJobs(D,lab,state).find(j=>j.id===act.slice(15));if(!j)return;sourceExample(j.partId,j.gap||1);sourcing.due=j.due;sourcing.destination=j.base;sourceSave();return render()}if(act.startsWith('src-part-source-')){const part=state.parts.find(p=>p.id===act.slice(16));if(!part)return;sourceExample(part.id,Math.max(1,M.coverage(state,part).gap));sourcing.due=part.due;sourceSave();return render()}if(act.startsWith('src-shipment-')){const r=sourcing.rfqs.find(r=>r.id===act.slice(13));if(!r||linkedRequest(r)?.status!=='Confirmed')throw Error('Supplier acceptance is required first.');const steps=['Not scheduled','Ready for dispatch','In transit','Delivered (simulation)'];r.shipment=steps[Math.min(steps.length-1,Math.max(0,steps.indexOf(r.shipment))+1)];r.events.push({text:'Logistics simulation: '+r.shipment,at:S.BASE});return sourceEvent('Updated simulated shipment; warehouse stock unchanged.')}if(act.startsWith('src-mode-'))return setMode(act.slice(9));if(act.startsWith('src-program-'))return programEditor(act.slice(12));if(act.startsWith('src-release-')){const r=sourcing.rfqs.find(r=>r.id===act.slice(12));return open('Release simulated RFQ?',`<p>${r.id}: ${r.qty} units to ${r.ids.length} selected suppliers, needed ${date(r.due)} at ${r.destination}.</p><p>No email or external request is sent. This changes the local workflow status.</p>${btn('Keep draft','close')}${btn('Release demo RFQ','src-send-'+r.id,'primary','check')}`)}if(act.startsWith('src-send-')){S.send(sourcing.rfqs.find(r=>r.id===act.slice(9)));close();return sourceEvent('Demo RFQ released locally. No supplier contacted.')}if(act.startsWith('src-responses-')){S.respond(D,sourcing.rfqs.find(r=>r.id===act.slice(14)));return sourceEvent('Synthetic quotes received. Compare documentation and delivery before choosing.')}if(act.startsWith('src-discard-')){sourcing.rfqs=sourcing.rfqs.filter(r=>r.id!==act.slice(12)||r.status!=='Draft');return sourceEvent('Draft discarded.')}if(act.startsWith('src-option-')){const [r,q]=act.slice(11).split('~');return optionReview(r,q)}switch(act){case'src-search-home':return sourceGo('Marketplace');case'src-example-bolt':return sourceExample('bolt',20,true);case'src-example-apu':return sourceExample('apu',1);case'src-example-housing':return sourceExample('housing',100);case'src-draft':return rfqDraft();case'src-programs':sourceGo('Fleet & maintenance');return;case'src-clear':Object.assign(sourcing,{partId:'all',query:'',supplier:'all',channel:'all',condition:'all',delivery:'all',selected:[]});return sourceEvent('Search filters cleared.');case'src-roi-export':return labDownload('skysupply-value-assumptions.json',JSON.stringify({synthetic:true,snapshot:S.BASE,assumptions:sourcing.roi,results:S.roi(sourcing.roi)},null,2),'application/json')}}catch(err){toast(err.message)}},true);
document.addEventListener('submit',e=>{const f=e.target;if(!['src-assistant','src-filters','src-rfq-draft','src-convert','src-program-form','src-roi','search-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity())return;const fd=new FormData(f);try{if(f.id==='src-assistant'){const input=String(fd.get('prompt')),parsed=S.interpret(D,input);if(!parsed.partId){sourcing.query=input;sourcing.partId='all';sourcing.selected=[];return sourceEvent('No exact component recognized. Use a demo part number or select the component filter.')}sourceExample(parsed.partId,parsed.qty||1,parsed.urgent);return toast('Interpreted the sample need. Confirm quantity and destination in the RFQ.')}if(f.id==='search-form'){sourcing.query=String(fd.get('query')).trim();sourcing.partId='all';sourcing.selected=[];search=sourcing.query;return sourceGo('Marketplace')}if(f.id==='src-filters'){const old=sourcing.partId;for(const [k,v] of fd)sourcing[k]=v;if(old!==sourcing.partId){sourcing.selected=[];sourcing.qty=1}return sourceEvent('Supplier search updated.')}if(f.id==='src-rfq-draft'){S.create(D,sourcing,{ids:sourcing.selected,qty:Number(fd.get('qty')),due:String(fd.get('due')),destination:String(fd.get('destination')),owner:String(fd.get('owner')),jobId:String(fd.get('jobId')||''),requiredCondition:String(fd.get('requiredCondition')||'Any'),documents:String(fd.get('documents')||''),org:lab.org});sourcing.selected=[];sourceGo('Quotes & shipping');return toast('RFQ draft saved for buyer review.')}if(f.id==='src-convert')return convertQuote(f.dataset.rfq,f.dataset.quote);if(f.id==='src-program-form'){sourcing.programs[f.dataset.type]={reference:String(fd.get('reference')).trim(),revision:String(fd.get('revision')).trim(),owner:String(fd.get('owner')).trim()};close();return sourceEvent('Saved an unverified program reference; sample targets unchanged.')}if(f.id==='src-roi'){const x=Object.fromEntries([...fd].map(([k,v])=>[k,Number(v)]));S.roi(x);sourcing.roi=x;return sourceEvent('Updated value assumptions. Delay exposure remains separate from labor ROI.')}}catch(err){toast(err.message)}},true);
document.addEventListener('change',e=>{if(e.target.id==='planning-horizon')return setMode(e.target.value);if(e.target.form?.id==='src-rfq-draft'&&e.target.name==='jobId'){const job=D.jobs.find(j=>j.id===e.target.value);if(job){e.target.form.elements.due.value=job.due;e.target.form.elements.destination.value=job.base}}if(e.target.dataset.sourceId){const id=e.target.dataset.sourceId,o=S.offers(D).find(o=>o.id===id);if(sourcing.partId==='all')sourcing.partId=o.partId;if(sourcing.partId!==o.partId){e.target.checked=false;return toast('Compare suppliers for one component at a time.')}sourcing.selected=e.target.checked?[...new Set([...sourcing.selected,id])]:sourcing.selected.filter(x=>x!==id);sourceSave();render()}if(e.target.dataset.rfqCarrier){const r=sourcing.rfqs.find(r=>r.id===e.target.dataset.rfqCarrier);r.carrier=e.target.value;sourceSave();render()}if(e.target.dataset.rfqService){const r=sourcing.rfqs.find(r=>r.id===e.target.dataset.rfqService);r.shipping=e.target.value;r.carrier='ups';sourceSave();render()}});
sourceSave();render();

const sourcingReview=review,sourcingRespond=respond;
function appendFreight(id){const a=state.actions.find(a=>a.id===id);if(a?.quoteRef)$('#dialog .dialog-body').insertAdjacentHTML('afterbegin',`<div class="program-callout"><strong>${esc(a.quoteRef)} · delivered estimate</strong><p>Parts ${money(a.qty*a.unitPrice)} + ${esc(a.shippingService)} ${money(a.shippingCost)} = ${money(a.qty*a.unitPrice+a.shippingCost)}. Taxes and duties excluded. Arrival assumes the selected handling/transit; a changed supplier date supersedes it.</p></div>`)}
review=function(id){sourcingReview(id);appendFreight(id)};
respond=function(id){sourcingRespond(id);appendFreight(id)};

const sourcingJobDetail=jobDetail,sourcingResolution=resolution;
jobDetail=function(id){sourcingJobDetail(id);if($('#dialog').open)$('#dialog .dialog-body').insertAdjacentHTML('beforeend',`<div class="dialog-actions">${btn('Compare suppliers for this component','src-job-source-'+id,'primary','search')}</div>`)};
resolution=function(id){sourcingResolution(id);if($('#dialog').open)$('#dialog .dialog-body').insertAdjacentHTML('afterbegin',`<div class="dialog-actions">${btn('Compare supplier quotes','src-part-source-'+id,'primary','search')}</div>`)};

/* Presentation navigation and repeatable guided scenarios. */
function tourStages(org){return org==='OEM'?[
['Control tower','See the production gap','Start with housing demand: 1,000 needed, 50 usable and 700 expected. The baseline gap is 250.','overview'],
['Metrics & Forecasting','Understand the delivery estimate','Open Why? on a PO. Try demand or delivery assumptions, then reset them before the sourcing example.','metrics'],
['Demand & commitments','Compare ways to close the gap','Open the housing requirement to compare stock, production and capacity reservations.','demand'],
['Marketplace','Find and compare sources','Select suppliers for the same component and prepare one RFQ. Complete and partial quantities remain distinct.','sources'],
['Quotes & shipping','Compare quotes and delivery','This step opens a labeled sample RFQ comparison. Change shipping, then review an option. No order is created automatically.','quotes'],
['Actions','Follow the decision','Create a request from a complete quote, approve as buyer, then open the named supplier response. Only an accepted, timely request changes expected coverage.','actions'],
['Value calculator','Discuss the possible value','Change purchasing effort and labor assumptions. Delay exposure stays separate from labor value.','value']
]:[
['Control tower','See maintenance material exposure','Start with the jobs needing attention. The baseline has five material-exposed work orders.','overview'],
['Fleet & maintenance','Inspect a specific maintenance need','Review WO-DEMO-27010. Compare a replacement purchase with a temporary loaner, then inspect replacement planning and program references.','fleet'],
['Marketplace','Find replacement suppliers','Compare sources for the service APU. Availability, documentation and part fit need review.','sources'],
['Quotes & shipping','Compare delivered options','This step opens a labeled sample APU RFQ tied to WO-DEMO-27010. Review arrival timing and delivered expense.','quotes'],
['Actions','Follow buyer and supplier approval','Create a purchase request or loaner request. Buyer approval alone does not close the job gap; the supplier must accept a timely date.','actions'],
['Metrics & Forecasting','Explore changes to the plan','Change delivery disruption or component utilization and inspect the resulting planning exposure.','metrics'],
['Value calculator','Discuss the possible value','Compare estimated purchasing effort with subscription assumptions. No actual savings are claimed.','value']
]}
function presentationGuide(){open('Choose your walkthrough',`<p class="guide-intro">A guided introduction for a first-time viewer. Each step explains what to show and opens the right workspace. Current saved requests remain available.</p><div class="presentation-choices"><section><span class="eyebrow">OEM · PRODUCTION & PROCUREMENT</span><h3>Can we build what is planned?</h3><p>Follow a component shortage through supplier readiness, sourcing, quotes and an approved response.</p>${btn('Start OEM walkthrough','present-start-OEM','primary','plane')}</section><section><span class="eyebrow">AIRLINE · MAINTENANCE & SOURCING</span><h3>Will the part reach the job in time?</h3><p>Follow a maintenance need through replacement planning, supplier quotes and a purchase or loaner response.</p>${btn('Start airline walkthrough','present-start-Airline','primary','plane')}</section></div><div class="presentation-reference"><h3>Explore the supporting pages</h3><p>Supplier network shows readiness and sharing. ERP data room exposes the records and imports. Data & assumptions explains the rules and limits.</p>${btn('Inspect ERP records','lab-nav-ERP data room','','file')}${btn('Open assumptions','nav-Data & assumptions','','note')}</div><div class="presentation-reset"><div><strong>Need a clean starting point?</strong><p>Use Reset demo to remove saved demo edits and requests. Export a readable backup first.</p></div>${btn('Reset demo…','present-reset','small','refresh')}</div>`)}
guide=presentationGuide;pitchDialog=presentationGuide;
function ensureQuoteExample(org){let r=sourcing.rfqs.find(r=>r.demoExample&&r.org===org);if(r)return r;const airline=org==='Airline';r=S.create(D,sourcing,{org,ids:airline?['apu_0','apu_1','apu_2','apu_3']:['housing_0','housing_1','housing_2','housing_3'],qty:airline?1:100,due:airline?'2026-12-04':'2027-02-12',destination:'PHX',owner:'Demo buyer',jobId:airline?'WO-DEMO-27010':''});S.send(r);S.respond(D,r);r.demoExample=true;r.events.push({text:'Presentation comparison example loaded explicitly',at:S.BASE});sourceSave();return r}
function openTourStep(org,index){const steps=tourStages(org);index=Math.max(0,Math.min(steps.length-1,index));const [view,,,key]=steps[index];close();sourcing.tour={org,index};lab.org=org;state.role='Buyer';state.view=view;if(index===0)sourcing.mode='short';if(key==='sources'){sourceExample(org==='OEM'?'housing':'apu',org==='OEM'?100:1);sourcing.due=org==='OEM'?'2027-02-12':'2026-12-04';sourcing.destination='PHX'}if(key==='quotes')ensureQuoteExample(org);labSave();sourceSave();save();render();window.scrollTo({top:0,behavior:'instant'})}
function tourBanner(){const t=sourcing.tour;if(!t)return '';const stages=tourStages(t.org),stage=stages[t.index];return `<section class="tour-banner"><div><span class="eyebrow">${t.org==='OEM'?'OEM':'AIRLINE'} WALKTHROUGH · ${t.index+1} OF ${stages.length}</span><strong>${stage[1]}</strong><p>${stage[2]}</p></div><div class="tour-controls">${t.index?btn('Back','present-step-'+(t.index-1),'small'):''}${btn(t.index===stages.length-1?'Finish walkthrough':'Next step',t.index===stages.length-1?'present-stop':'present-step-'+(t.index+1),'small primary','arrow')}${btn('Exit guide','present-stop','small')}</div></section>`}
function presentationPolish(){const main=$('main'),navigation=$('nav');if(!main||!navigation)return;const order=['Control tower','Metrics & Forecasting','Fleet & maintenance','Demand & commitments','Supplier network','Marketplace','Quotes & shipping','Actions','Value calculator','ERP data room','Data & assumptions'];for(const name of order){const node=navigation.querySelector(`[data-action="nav-${name}"]`);if(node)navigation.appendChild(node)}const demandNode=navigation.querySelector('[data-action="nav-Demand & commitments"]');if(demandNode)demandNode.hidden=lab.org==='Airline';const fleetNode=navigation.querySelector('[data-action="nav-Fleet & maintenance"]');if(fleetNode&&lab.org==='OEM'){fleetNode.title='Switch to the airline maintenance workspace';fleetNode.querySelector('span').textContent='Airline maintenance'}const oldGuide=$('.sidebar-bottom button[data-action="guide"]');if(oldGuide)oldGuide.innerHTML=icon('link')+'Walkthrough guide';const help=$('.help-button');if(help){help.textContent='Guide';help.setAttribute('aria-label','Presentation guide');help.title='Choose an OEM or airline walkthrough'}if(state.role==='Buyer'&&lab.org==='Airline'&&state.view==='Demand & commitments'){state.view='Fleet & maintenance';const node=navigation.querySelector('[data-action="nav-Fleet & maintenance"]');node?.classList.add('active');demandNode?.classList.remove('active')}if(state.role==='Buyer'&&sourcing.tour)main.insertAdjacentHTML('afterbegin',tourBanner());const prepare=main.querySelector('[data-action="src-draft"]');if(prepare&&!sourcing.selected.length){prepare.disabled=true;prepare.title='Select one or more suppliers first'}if(state.view==='Quotes & shipping'&&state.role==='Buyer'){for(const card of main.querySelectorAll('.rfq-card')){const r=sourcing.rfqs.find(r=>card.querySelector('.code')?.textContent.startsWith(r.id+' ·'));if(r?.demoExample)card.querySelector('.action-top').insertAdjacentHTML('beforeend',pill('Comparison example'))}if(!sourcing.rfqs.some(r=>r.org===lab.org))main.querySelector('.empty')?.insertAdjacentHTML('beforeend',btn('Load a comparison example','present-quotes','', 'spark'))}applyProductCopy()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]'),act=el?.dataset.action;if(!act?.startsWith('present-'))return;e.preventDefault();e.stopImmediatePropagation();try{if(act.startsWith('present-start-'))return openTourStep(act.slice(14),0);if(act.startsWith('present-step-'))return openTourStep(sourcing.tour.org,Number(act.slice(13)));switch(act){case'present-stop':delete sourcing.tour;return sourceEvent('Walkthrough closed. Your scenario is saved.');case'present-quotes':ensureQuoteExample(lab.org);return sourceEvent('Loaded a labeled presentation comparison; no purchase request created.');case'present-reset':return open('Reset all demo workspaces?',`<p>This resets demo orders, RFQs, scenario assumptions, inventory edits, program references and calculator inputs in this browser. Concept 1 stays separate.</p><p>Export first to keep a readable record. There is no automatic JSON restore.</p><div class="dialog-actions">${btn('Export full backup','lab-export','','download')}${btn('Keep current work','close')}${btn('Reset demo data','present-reset-confirm','primary','refresh')}</div>`);case'present-reset-confirm':state=M.initial();lab=A.initial();lab.installedOverrides={};sourcing=S.initial();search='';filterPart='all';filterChannel='All';inventoryPreview=null;labQuery='';labPage=1;fleetTab='jobs';state.view='Control tower';ensureNetworkCatalog();labSave();sourceSave();save();close();render();window.scrollTo({top:0,behavior:'instant'});return toast('Demo reset to its baseline. Choose Guide to start a walkthrough.')}}catch(err){toast(err.message)}},true);
function productText(value){return String(value).replace(/SYNTHETIC BACKTEST \/ NOT REAL ACCURACY/g,'MODEL EVALUATION / SAMPLE HISTORY').replace(/ERP DATA ROOM \/ TRACEABLE FICTION/g,'ERP DATA ROOM / SOURCE RECORDS').replace(/Recognizable records\. Explicitly fictional numbers\./g,'Source coverage and record definitions.').replace(/LOCAL SIMULATION/g,'LOCAL WORKSPACE').replace(/MANUAL DEMO INPUTS/g,'MANUAL UPDATES').replace(/Original marketplace 01/g,'').replace(/Concept 1 stays separate\./g,'').replace(/Concept 02/g,'').replace(/CONCEPT 02/g,'').replace(/Concept 01/g,'').replace(/DEMO-AC-/g,'AC-').replace(/WO-DEMO-/g,'WO-').replace(/DEMO-SN-/g,'SN-').replace(/DEMO-/g,'SS-').replace(/Data & assumptions/g,'Data & methodology').replace(/Demo aircraft/gi,'Aircraft').replace(/Demo buyer/gi,'Procurement team').replace(/Demo planner/gi,'Maintenance planner').replace(/Review & release demo RFQ/g,'Review & release RFQ').replace(/Release demo RFQ/g,'Release RFQ').replace(/Simulate supplier responses/g,'Preview supplier quotes').replace(/Simulate shipment update/g,'Preview shipment update').replace(/Approve scenario request/g,'Approve request').replace(/Accept in scenario/g,'Confirm acceptance').replace(/Create purchase review request/g,'Create purchase request').replace(/Run pitch scenario/g,'Explore planning scenarios').replace(/Sample trace pack/gi,'Trace pack available').replace(/sample trace pack/gi,'Trace pack available').replace(/A judge-ready walkthrough/g,'Workspace walkthrough').replace(/Presentation guide/g,'Workspace guide').replace(/Presentation example/g,'Comparison example').replace(/Start OEM walkthrough/g,'Explore OEM workspace').replace(/Start airline walkthrough/g,'Explore airline workspace').replace(/Reset all demo workspaces/g,'Reset workspace').replace(/Reset demo data/g,'Reset workspace data').replace(/Reset demo/g,'Reset workspace').replace(/Demo reset/g,'Workspace reset').replace(/Load a comparison example/g,'Open a quote comparison').replace(/SOURCING ASSISTANT · GUIDED DEMO/g,'SOURCING ASSISTANT').replace(/\bdemo\b/gi,'workspace').replace(/\bsynthetic\b/gi,'sample').replace(/\bfictional\b/gi,'sample').replace(/\bsimulated\b/gi,'preview').replace(/\bsimulate\b/gi,'Preview')}
function applyProductCopy(){const strip=$('.demo-strip');if(strip)strip.innerHTML=`<span>OPERATIONS WORKSPACE <b>Planning date ${date(S.BASE)}</b></span><button data-action="nav-ERP data room">${recordCount()} source records ${icon('arrow')}</button>`;const bottom=$('.sidebar-bottom');if(bottom)bottom.innerHTML=`<button data-action="guide">${icon('link')}Workspace guide</button><button data-action="nav-Data & assumptions">${icon('sliders')}Data & methodology</button><small>SkySupply · Connected aerospace operations</small>`;for(const note of document.querySelectorAll('.simulation-note'))note.remove();for(const a of document.querySelectorAll('a[href="https://stevedog-krav.github.io/skysupply-demo/"]'))a.closest('.reset-zone')?.remove();for(const label of document.querySelectorAll('.dialog-head .eyebrow'))label.textContent='SKYSUPPLY / OPERATIONS';const help=$('.help-button');if(help){help.textContent='Guide';help.setAttribute('aria-label','Workspace guide')}for(const node of document.querySelectorAll('nav .nav-item')){node.setAttribute('aria-current',node.classList.contains('active')?'page':'false')}for(const b of document.querySelectorAll('[data-action^="src-mode-"]'))b.setAttribute('aria-pressed',String(b.classList.contains('selected')));const walker=document.createTreeWalker($('#app'),NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.parentElement.closest('script,style'))node.nodeValue=productText(node.nodeValue)}if($('#dialog').open){const w=document.createTreeWalker($('#dialog'),NodeFilter.SHOW_TEXT);while(node=w.nextNode())node.nodeValue=productText(node.nodeValue)}for(const el of document.querySelectorAll('[placeholder],[title],[aria-label]'))for(const attr of ['placeholder','title','aria-label'])if(el.hasAttribute(attr))el.setAttribute(attr,productText(el.getAttribute(attr)));for(const field of document.querySelectorAll('input[type="text"],input:not([type])'))if(/DEMO-/.test(field.value))field.value=productText(field.value);const footer=$('main footer');if(footer){footer.innerHTML=`<span>${icon(saved?'check':'warning')}${saved?'Changes saved in this browser':'Changes not saved — export your work'}</span><span class="sample-notice">Sample data · No live orders or payments</span>`}if(state.role==='Buyer'&&state.view==='Data & assumptions'){const heading=$('main h1');if(heading)heading.innerHTML='Understand the data.<br><em>Trust the process.</em>'}}
const productOpen=open,productToast=toast;
open=function(title,body){productOpen(productText(title),body);applyProductCopy()};
toast=function(message){productToast(productText(message))};
simNote=function(){return ''};
for(const part of state.parts){const code=D.catalog.find(p=>p.id===part.id)?.code;if(code)part.code=code}
render();

function chosenShipping(r,q){if(r.chosenShipping&&r.chosenQuote===q.id)return r.chosenShipping;const opts=S.carrierOptions(q,Math.min(r.qty,q.qty),r.destination,r.shipping);return opts.find(o=>o.id===(r.carrier||'ups'))||opts[0]}
function carrierComparison(r){if(r.actionRef&&r.chosenShipping?.id==='recorded')return `<section class="carrier-comparison"><h3>Recorded transport estimate</h3><p>${esc(r.chosenShipping.name)} · ${money(r.chosenShipping.cost)} · expected ${date(r.chosenShipping.arrival)}.</p><p class="fine-print">Preserved from the existing purchase request. No carrier connection or new quote is inferred.</p></section>`;const q=r.quotes.find(q=>q.docs&&q.quotedQty>=r.qty&&(!r.requiredCondition||r.requiredCondition==='Any'||q.condition===r.requiredCondition));if(!q)return '';const opts=S.carrierOptions(q,r.qty,r.destination,r.shipping);return `<section class="carrier-comparison"><div class="panel-head"><div><span class="eyebrow">CARRIER & SERVICE COMPARISON</span><h3>Compare transport estimates</h3><p>Reference shipment: ${q.name} → ${r.destination}. Choosing a carrier recalculates each supplier’s delivered total.</p></div></div><div class="carrier-options">${opts.map(o=>`<label class="carrier-option ${(r.carrier||'ups')===o.id?'selected':''}"><input type="radio" name="carrier-${r.id}" data-rfq-carrier="${r.id}" value="${o.id}" ${(r.carrier||'ups')===o.id?'checked':''} ${r.actionRef?'disabled':''}><span><strong>${o.provider}</strong><small>${o.name}</small><b>${money(o.cost)}</b><small>Estimated arrival ${date(o.arrival)}</small><small>${o.eligibility}</small></span></label>`).join('')}</div><p class="fine-print">Rate estimates, not carrier-issued quotes. Amazon Shipping is shown only for standard parcel scenarios; freight, AOG and oversized components require other arrangements. Booking requires a confirmed carrier account, package details and service acceptance.</p></section>`}

// Preserve freight figures already selected before carrier-level comparisons were introduced.
for(const r of sourcing.rfqs){if(!r.actionRef||r.chosenShipping)continue;const a=(r.org==='OEM'?state.actions:lab.actions).find(a=>a.id===r.actionRef),q=r.quotes.find(q=>q.id===r.chosenQuote);if(!a||!q)continue;const sh=S.shipping(q,Math.min(r.qty,q.qty),r.destination).find(sh=>sh.id===r.shipping);if(!sh)continue;r.chosenShipping={...sh,id:'recorded',provider:'Recorded transport estimate',name:a.shippingService||sh.name,cost:a.shippingCost??sh.cost,arrival:a.date||a.eta||sh.arrival};r.carrier='recorded'}
sourceSave();render();

function horizonHero(airline,urgent,count){const title=urgent?(airline?'Every hour matters.<br>Source for the next job.':'See the urgent constraint.<br>Choose the next response.'):(airline?'Plan the next removal.<br>Prepare the next part.':'See the next build.<br>Prepare the supply.');return `<section class="intelligence-hero"><div><span class="eyebrow">${orgName().toUpperCase()} / ${urgent?'URGENT MATERIAL COVERAGE':'LONG-RANGE READINESS'}</span><h2>${title}</h2><p>${urgent?'Focus on dated needs within the next seven days.':'Connect future needs with component planning targets and supplier readiness.'}</p></div><div class="hero-signal"><span>${airline&&!urgent?'PROJECTED COMPONENT TARGETS':'MATERIAL EXCEPTIONS IN WINDOW'}</span><strong>${count}</strong><p>${airline&&!urgent?'targets in the selected horizon':'dated requirements with an uncovered need'}</p>${btn('Find sourcing options','src-search-home','','arrow')}</div></section>`}
